        if len(vals)>=2:
            c=max(set(vals),key=vals.count)
            bands.append((r,c))
    # Vertical marker columns are repeated single-color cells in sparse rows.
    counts={}
    for j in range(w):
        seq=[grid[i][j] for i in range(h) if grid[i][j]]
        if any(grid[i][j] for i in range(h-3,h)): counts[j]=1
    for j,marker in counts.items():
        for k,(r,c) in enumerate(bands):
            if grid[r][j]!=0: continue
            lo=(bands[k-1][0]+1) if k else 0
            hi=(bands[k+1][0]+1) if k+1<len(bands) else h
            for i in range(lo,hi):
                if a[i][j]==0: a[i][j]=c
    # Complete each horizontal bar between its first and last matching cell.
    for r,c in bands:
        ix=[j for j,v in enumerate(grid[r]) if v==c]
